import { CHAIN } from './chain-config.js';
import { sharedReadProvider } from './read-provider.js';

// Leaving these fields absent lets the wallet choose a much larger default on
// high-gas game calls. Read the live base fee; never carry a fixed gas price
// across blocks/networks.
// Sampled 2026-10-18 (40 blocks): base fee ~17 wei, but about one block in
// five came from a builder that drops tips below ~0.001 gwei, so a 1-wei tip
// waited extra slots. A 0.001 gwei tip costs ~0.000001 ETH on a 1M-gas call.
// The max fee carries a fixed 0.01 gwei cushion over 2x base: at a ~17 wei
// base fee, 2x alone left a stuck (and nonce-blocking) transaction after any
// small spike. The cushion is never charged, only reserved (0.00008 ETH on an
// 8M-gas call), so affordability checks stay close to the old policy.
const SEPOLIA_TIP_WEI = 1_000_000n;
const SEPOLIA_MAX_FEE_CUSHION_WEI = 10_000_000n;
// A tap on BUY is the one read the player is waiting on: a single refused or dropped request (a
// phone coming back from the wallet app, a free RPC resting after a 429) must not end the purchase.
const FEE_READ_ATTEMPTS = 3;
const FEE_RETRY_MAX_MS = 3_000;
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export async function sepoliaFeeOverrides({ chainId = CHAIN.id, provider, retryDelayMs = 1_000 } = {}) {
  if (Number(chainId) !== 11155111) return {};
  for (let attempt = 1; ; attempt += 1) {
    try {
      const block = await (provider ?? sharedReadProvider()).getBlock('latest');
      if (block?.baseFeePerGas == null) throw new Error('Missing base fee');
      const baseFee = BigInt(block.baseFeePerGas);
      if (baseFee < 0n) throw new Error('Invalid base fee');
      return {
        maxPriorityFeePerGas: SEPOLIA_TIP_WEI,
        maxFeePerGas: baseFee * 2n + SEPOLIA_TIP_WEI + SEPOLIA_MAX_FEE_CUSHION_WEI,
      };
    } catch (cause) {
      if (attempt >= FEE_READ_ATTEMPTS) throw new Error('Could not read Sepolia gas fees. Please retry.', { cause });
      // The read breaker says when it reopens; otherwise back off a little more each time.
      const until = Number(cause?.retryAt) - Date.now();
      const delay = Number.isFinite(until) && until > 0 ? until : retryDelayMs * attempt;
      await wait(Math.min(FEE_RETRY_MAX_MS, Math.max(0, delay)));
    }
  }
}

/** Preserve deliberate caller overrides; otherwise attach the testnet policy. */
export async function withTransactionFees(request, options) {
  if (request?.gasPrice != null || request?.maxFeePerGas != null || request?.maxPriorityFeePerGas != null) {
    return request;
  }
  return { ...request, ...await sepoliaFeeOverrides(options) };
}

/** Affordability checks must use the same fee policy as the eventual send. */
export async function transactionFeeData(provider) {
  if (Number(CHAIN.id) === 11155111) return sepoliaFeeOverrides();
  return typeof provider?.getFeeData === 'function' ? provider.getFeeData() : null;
}
